import type { CodeComponentMeta } from "@plasmicapp/host/registerComponent";
import { Button } from "antd";
import React from "react";
import { buttonComponentName } from "./names";
import { Registerable, registerComponentHelper } from "./utils";

export type AntdButtonProps = Omit<
  React.ComponentPropsWithoutRef<typeof Button>,
  "target"
> & {
  submitsForm?: boolean;
  target?: React.ComponentProps<typeof Button>["target"] | boolean;
};

export const AntdButton: React.ForwardRefExoticComponent<
  React.PropsWithoutRef<AntdButtonProps> &
    React.RefAttributes<React.ComponentRef<typeof Button>>
> = React.forwardRef<React.ComponentRef<typeof Button>, AntdButtonProps>(
  function AntdButton(props, ref) {
    const { submitsForm = false, ...rest } = props;
    const target =
      props.target === true
        ? "_blank"
        : props.target === false
          ? undefined
          : props.target;
    return (
      <Button
        {...rest}
        ref={ref}
        htmlType={props.htmlType ?? (submitsForm ? "submit" : "button")}
        target={target}
      />
    );
  },
);

export function registerButton(loader?: Registerable) {
  registerComponentHelper(loader, AntdButton, {
    name: buttonComponentName,
    displayName: "Button",
    description: "Trigger a user action such as submit, reset, confirm or open an overlay. Supports text, icons, loading and disabled states; use href for link navigation.",
    canvasText: { prop: "children", selector: ":scope > span:not(.ant-btn-icon)" },
    props: getButtonProps(),
    importPath: "@shiguang-lab/plasmic-antd6/skinny/registerButton",
    importName: "AntdButton",
  });
}

